messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Red vs Blue Car Race</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; }
        canvas { display: block; }
        #info {
            position: absolute;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
            font-family: sans-serif;
            font-size: 24px;
            font-weight: bold;
            color: white;
            text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">Race in progress...</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const TRACK_LENGTH = 200;
        const CARS_SPACING = 4;
        const CAMERA_HEIGHT = 15;
        const CAMERA_DISTANCE = 30;
        const RACE_DURATION = 15; // seconds for a full loop

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB);
        scene.fog = new THREE.Fog(0x87CEEB, 20, 150);

        const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 300);
        camera.position.set(0, CAMERA_HEIGHT, CAMERA_DISTANCE);
        camera.lookAt(0, 0, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 1);
        dirLight.position.set(50, 100, 50);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 2048;
        dirLight.shadow.mapSize.height = 2048;
        dirLight.shadow.camera.near = 0.5;
        dirLight.shadow.camera.far = 500;
        dirLight.shadow.camera.left = -100;
        dirLight.shadow.camera.right = 100;
        dirLight.shadow.camera.top = 100;
        dirLight.shadow.camera.bottom = -100;
        scene.add(dirLight);

        // --- Environment ---
        // Ground
        const groundGeo = new THREE.PlaneGeometry(300, 1000);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x3a7e45 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.z = -100;
        ground.receiveShadow = true;
        scene.add(ground);

        // Track
        const trackGeo = new THREE.PlaneGeometry(20, 1000);
        const trackMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
        const track = new THREE.Mesh(trackGeo, trackMat);
        track.rotation.x = -Math.PI / 2;
        track.position.z = -100;
        track.position.y = 0.01; // Slightly above ground
        track.receiveShadow = true;
        scene.add(track);

        // Finish Line
        const finishLineGeo = new THREE.PlaneGeometry(20, 2);
        const finishLineMat = new THREE.MeshStandardMaterial({ color: 0xFFFFFF });
        const finishLine = new THREE.Mesh(finishLineGeo, finishLineMat);
        finishLine.rotation.x = -Math.PI / 2;
        finishLine.position.set(0, 0.02, TRACK_LENGTH);
        scene.add(finishLine);

        // Checkerboard pattern for finish line
        const checkerGeo = new THREE.PlaneGeometry(20, 2);
        const canvas = document.createElement('canvas');
        canvas.width = 64;
        canvas.height = 64;
        const ctx = canvas.getContext('2d');
        ctx.fillStyle = 'white';
        ctx.fillRect(0, 0, 64, 64);
        ctx.fillStyle = 'black';
        for (let i = 0; i < 8; i++) {
            for (let j = 0; j < 8; j++) {
                if ((i + j) % 2 === 0) ctx.fillRect(i * 8, j * 8, 8, 8);
            }
        }
        const checkerTex = new THREE.CanvasTexture(canvas);
        const checkerMat = new THREE.MeshStandardMaterial({ map: checkerTex });
        const checkerLine = new THREE.Mesh(checkerGeo, checkerMat);
        checkerLine.rotation.x = -Math.PI / 2;
        checkerLine.position.set(0, 0.03, TRACK_LENGTH);
        scene.add(checkerLine);

        // Finish Line Pillars
        const pillarGeo = new THREE.BoxGeometry(1, 10, 1);
        const pillarMat = new THREE.MeshStandardMaterial({ color: 0x888888 });
        const pillar1 = new THREE.Mesh(pillarGeo, pillarMat);
        pillar1.position.set(-10.5, 5, TRACK_LENGTH);
        pillar1.castShadow = true;
        scene.add(pillar1);
        const pillar2 = new THREE.Mesh(pillarGeo, pillarMat);
        pillar2.position.set(10.5, 5, TRACK_LENGTH);
        pillar2.castShadow = true;
        scene.add(pillar2);

        // Banner
        const bannerGeo = new THREE.BoxGeometry(21, 2, 1);
        const bannerMat = new THREE.MeshStandardMaterial({ color: 0xFFD700 });
        const banner = new THREE.Mesh(bannerGeo, bannerMat);
        banner.position.set(0, 10, TRACK_LENGTH);
        banner.castShadow = true;
        scene.add(banner);

        // --- Car Creation ---
        function createCar(color) {
            const carGroup = new THREE.Group();

            // Body
            const bodyGeo = new THREE.BoxGeometry(2, 1, 4);
            const bodyMat = new THREE.MeshStandardMaterial({ color: color });
            const body = new THREE.Mesh(bodyGeo, bodyMat);
            body.position.y = 1;
            body.castShadow = true;
            carGroup.add(body);

            // Cabin
            const cabinGeo = new THREE.BoxGeometry(1.8, 0.8, 2);
            const cabinMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
            const cabin = new THREE.Mesh(cabinGeo, cabinMat);
            cabin.position.y = 1.8;
            cabin.position.z = -0.5;
            cabin.castShadow = true;
            carGroup.add(cabin);

            // Wheels
            const wheelGeo = new THREE.CylinderGeometry(0.5, 0.5, 0.4, 16);
            const wheelMat = new THREE.MeshStandardMaterial({ color: 0x111111 });
            const wheels = [
                { x: -1.1, z: 1.2 }, { x: 1.1, z: 1.2 },
                { x: -1.1, z: -1.2 }, { x: 1.1, z: -1.2 }
            ];
            wheels.forEach(pos => {
                const wheel = new THREE.Mesh(wheelGeo, wheelMat);
                wheel.rotation.z = Math.PI / 2;
                wheel.position.set(pos.x, 0.5, pos.z);
                wheel.castShadow = true;
                carGroup.add(wheel);
            });

            // Headlights
            const lightGeo = new THREE.SphereGeometry(0.3, 8, 8);
            const lightMat = new THREE.MeshStandardMaterial({ color: 0xFFFF00, emissive: 0xFFFF00 });
            const light1 = new THREE.Mesh(lightGeo, lightMat);
            light1.position.set(-0.6, 1, 2.1);
            carGroup.add(light1);
            const light2 = new THREE.Mesh(lightGeo, lightMat);
            light2.position.set(0.6, 1, 2.1);
            carGroup.add(light2);

            return carGroup;
        }

        const redCar = createCar(0xFF0000);
        const blueCar = createCar(0x0000FF);
        scene.add(redCar);
        scene.add(blueCar);

        // --- Animation Logic ---
        let startTime = null;
        const infoDiv = document.getElementById('info');

        function animate(time) {
            requestAnimationFrame(animate);

            if (!startTime) startTime = time;
            const elapsed = (time - startTime) / 1000; // seconds
            const cycleTime = elapsed % RACE_DURATION;

            // Calculate positions based on time
            // Blue car: starts ahead, leads early, then gets overtaken
            // Red car: starts behind, accelerates, overtakes mid-race, wins
            const bluePos = (cycleTime / RACE_DURATION) * TRACK_LENGTH;
            const redPos = (Math.pow(cycleTime / RACE_DURATION, 1.5) * TRACK_LENGTH);

            // Position cars
            blueCar.position.set(-CARS_SPACING, 0, bluePos);
            redCar.position.set(CARS_SPACING, 0, redPos);

            // Camera follows the leading car
            const leadCar = redPos > bluePos ? redCar : blueCar;
            const targetZ = leadCar.position.z;
            camera.position.z = targetZ + CAMERA_DISTANCE;
            camera.position.y = CAMERA_HEIGHT;
            camera.lookAt(0, 0, targetZ);

            // Update info text
            if (redPos > TRACK_LENGTH) {
                infoDiv.textContent = "Red Car Wins!";
                infoDiv.style.color = "#FF4444";
            } else if (bluePos > TRACK_LENGTH) {
                infoDiv.textContent = "Blue Car Wins!";
                infoDiv.style.color = "#4444FF";
            } else {
                infoDiv.textContent = "Race in progress...";
                infoDiv.style.color = "white";
            }

            renderer.render(scene, camera);
        }

        // Handle window resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start animation
        animate(0);
    </script>
</body>
</html>
```
